/** Live events over gRPC, as an alternative to webhooks for clients that only use the core. */
export type EventServiceService = typeof EventServiceService;
export const EventServiceService = {
  /**
   * Streams events from the moment of the call. Delivery is at most once: events that happen
   * while the client is disconnected are not replayed. Use webhooks with Redis for retries.
   * The headers of the answer arrive when the subscription starts. The stream ends with
   * UNAVAILABLE when the core stops.
   */
  subscribe: {
    path: "/calyx.core.v1.EventService/Subscribe" as const,
    requestStream: false as const,
    responseStream: true as const,
    requestSerialize: (value: SubscribeRequest): Buffer => Buffer.from(SubscribeRequest.encode(value).finish()),
    requestDeserialize: (value: Buffer): SubscribeRequest => SubscribeRequest.decode(value),
    responseSerialize: (value: Event): Buffer => Buffer.from(Event.encode(value).finish()),
    responseDeserialize: (value: Buffer): Event => Event.decode(value),
  },
} as const;

export interface EventServiceServer extends UntypedServiceImplementation {
  /**
   * Streams events from the moment of the call. Delivery is at most once: events that happen
   * while the client is disconnected are not replayed. Use webhooks with Redis for retries.
   * The headers of the answer arrive when the subscription starts. The stream ends with
   * UNAVAILABLE when the core stops.
   */
  subscribe: handleServerStreamingCall<SubscribeRequest, Event>;
}

export interface EventServiceClient extends Client {
  /**
   * Streams events from the moment of the call. Delivery is at most once: events that happen
   * while the client is disconnected are not replayed. Use webhooks with Redis for retries.
   * The headers of the answer arrive when the subscription starts. The stream ends with
   * UNAVAILABLE when the core stops.
   */
  subscribe(request: SubscribeRequest, options?: Partial<CallOptions>): ClientReadableStream<Event>;
  subscribe(
    request: SubscribeRequest,
    metadata?: Metadata,
    options?: Partial<CallOptions>,
  ): ClientReadableStream<Event>;
}

export const EventServiceClient = makeGenericClientConstructor(
  EventServiceService,
  "calyx.core.v1.EventService",
) as unknown as {
  new (address: string, credentials: ChannelCredentials, options?: Partial<ClientOptions>): EventServiceClient;
  service: typeof EventServiceService;
  serviceName: string;
};

